def evaluate(expr: str) -> float:
    """
    Evaluate a mathematical expression using a recursive descent parser.
    This function handles +, -, *, / operators and parentheses with proper precedence.
    """
    def parse_expression(index):
        nonlocal expr
        total, index = parse_term(index)
        while index < len(expr):
            if expr[index] == '+':
                index += 1
                value, index = parse_term(index)
                total += value
            elif expr[index] == '-':
                index += 1
                value, index = parse_term(index)
                total -= value
            else:
                break
        return total, index

    def parse_term(index):
        nonlocal expr
        total, index = parse_factor(index)
        while index < len(expr):
            if expr[index] == '*':
                index += 1
                value, index = parse_factor(index)
                total *= value
            elif expr[index] == '/':
                index += 1
                value, index = parse_factor(index)
                total /= value
            else:
                break
        return total, index

    def parse_factor(index):
        nonlocal expr
        if index < len(expr) and expr[index] == '(':
            index += 1
            value, index = parse_expression(index)
            if index < len(expr) and expr[index] == ')':
                index += 1
                return value, index
            else:
                raise ValueError("Mismatched parentheses")
        else:
            start = index
            while index < len(expr) and (expr[index].isdigit() or expr[index] == '.'):
                index += 1
            if start == index:
                raise ValueError("Invalid number")
            return float(expr[start:index]), index

    # Remove whitespace from the expression
    expr = expr.replace(" ", "")
    result, remaining_index = parse_expression(0)
    if remaining_index != len(expr):
        raise ValueError("Invalid expression")
    return result
